/// `max_completion_tokens` and rejects a custom `temperature`.
private static func isReasoningModel(_ modelID: String) -> Bool {
    // Strip any provider prefix such as "openai/" or "openai:".
    let bare = modelID.lowercased().split(whereSeparator: { $0 == "/" || $0 == ":" }).last.map(String.init) ?? modelID.lowercased()
    // OpenAI o-series: o1, o3, o4, o5… plus -mini/-pro/-preview variants.
    if let first = bare.first, first == "o",
